---@meta
-- maki plugin API stubs for EmmyLua / lua_ls.
--
-- Hand-written from the Lua API reference (generated by `maki-docgen`).
-- Only signatures confirmed by that reference are included here; anything
-- uncertain is marked with a "-- UNCERTAIN:" comment rather than invented.
-- This file is `---@meta`, so it never affects runtime: it only provides
-- hover/completion for plugin authors.
--
-- Fallible operations return `(value, err)` pairs instead of throwing; check
-- `err` before using `value`. Sensitive APIs (`maki.fs` reads/writes) need
-- the matching permission in the plugin's `plugin.toml` (`fs_read`,
-- `fs_write`, `net`, `run`, `env`).

--------------------------------------------------------------------------------
-- Shared aliases
--------------------------------------------------------------------------------

---@alias MakiActionName
---| '"file_picker"' # Built-in file picker.
---| '"search"' # Built-in search.
---| '"help"' # Built-in help.
---| '"plan_toggle"' # Toggle plan mode.
---| '"plan_editor"' # Open the plan editor.
---| '"edit_input"' # Edit the chat input.
---| '"pop_queue"' # Pop the prompt queue.
---| '"prev_chat"' # Focus the previous chat.
---| '"next_chat"' # Focus the next chat.
---| '"model_picker"' # Open the model picker.

---@alias MakiSessionMode
---| '"build"' # Normal build mode.
---| '"plan"' # Plan mode.

---@alias MakiThinking string|number
-- Thinking level for `maki.model.set`: `"off"`, `"adaptive"`, an effort
-- level (`"minimal"` to `"max"`), a token budget (number), or `""` to toggle.

---@alias MakiEventName string
-- Built-in autocmd events (custom event names fired via `exec_autocmds`
-- are also accepted): `"TurnStart"`, `"TurnEnd"`, `"TurnError"`,
-- `"ToolStart"`, `"ToolDone"`, `"AutoCompacting"`, `"CompactionDone"`,
-- `"PlanReady"`, `"SessionReset"`, `"SessionEnd"`, `"SessionFocusChanged"`,
-- `"SessionStatusChanged"`, `"SessionTitleChanged"`, `"TaskStatusChanged"`,
-- `"TaskFocusChanged"`, `"ModelChanged"`, `"InputChanged"`, `"FileIndexReady"`.

--------------------------------------------------------------------------------
-- 1. `maki`: the global entry point
--------------------------------------------------------------------------------

---@class MakiTimer
-- Handle returned by `maki.defer_fn`. `:stop()` cancels the callback.
maki_Timer = {}

---Cancel the pending callback. Safe to call more than once; does nothing
---once the callback has already run.
function maki_Timer:stop() end

---@class MakiSplitOpts
---@field plain? boolean Treat `sep` as literal text instead of a Lua pattern.
---@field trimempty? boolean Drop empty pieces from the start/end of the result.

---@class MakiNotifyOpts
---@field title? string Label shown in front of the message. Free-form otherwise.

---@alias MakiNotifyHandler fun(msg: string, level: string|nil, opts: table|nil)
-- Handler `function(msg, level?, opts?)` for every `maki.notify` call.

---@class Maki
---@field keymap MakiKeymap Key mappings (normal mode only).
---@field ui MakiUi Interactive UI builders.
---@field api MakiApi Plugin registration.
---@field model MakiModel Model behind the focused session.
---@field log MakiLog Structured logging.
---@field fs MakiFs File-system utilities.
---@field session MakiSession Host session primitives.
---@field plan MakiPlan Plan-mode surface.
---@field env MakiEnv Paths to maki's own directories.
---@field pack MakiPack Global package declarations and state.
maki = {}

---Apply personal configuration. Only available inside `init.lua` (not in
---plugins) and callable at most once.
---@param config table Configuration table (same keys as the Configuration reference).
function maki.setup(config) end

---Split `s` at each occurrence of `sep` (a Lua pattern unless `plain` is
---set); an empty `sep` splits into single characters. Mirrors `vim.split`.
---@param s string String to split.
---@param sep string Separator pattern (or literal text with `plain`).
---@param opts? MakiSplitOpts
---@return string[] pieces List of split pieces.
function maki.split(s, sep, opts) end

---Run `callback` once after `ms` milliseconds. Fires even if the scheduling
---tool call has ended or was cancelled. Errors raised by the callback are
---logged and dropped. For repeating work, use a `maki.async.sleep` loop.
---@param callback fun() Called with no arguments.
---@param ms integer Delay in milliseconds. Zero fires on the next tick.
---@return MakiTimer handle Handle whose `:stop()` cancels a pending callback (debounce).
function maki.defer_fn(callback, ms) end

---Show a one-line notice (default: via `maki.ui.flash`; to the log when
---there is no UI). Once a plugin calls `set_notify_handler`, every notice
---goes through that handler instead.
---@param msg string Notice text.
---@param level? string Severity name such as `"info"`, `"warn"`, `"error"`. Reaches the handler untouched; the default ignores it.
---@param opts? MakiNotifyOpts
function maki.notify(msg, level, opts) end

---Install the process-wide handler for `maki.notify`; pass `nil` to restore
---the default. Keep it short and hand real work to async tasks. Errors are
---logged and fall back to `maki.ui.flash`.
---@param handler? MakiNotifyHandler Handler `function(msg, level?, opts?)`, or nil.
function maki.set_notify_handler(handler) end

---Load an installed package that is dormant (`load = false` in `pack.add`,
---or an `opt` hand-installed package). Queued until the calling task returns.
---@param name string Package name.
function maki.packadd(name) end

--------------------------------------------------------------------------------
-- 2. `maki.keymap`
--------------------------------------------------------------------------------

---@class MakiKeymapOpts
---@field desc? string Short description shown in the keymap list.
---@field unique? boolean Fail (naming the owner) when the key is already mapped. Default false.

---@class MakiKeymap
-- Bindings are global, stack per plugin, and belong to the plugin that set
-- them. Only normal mode (`"n"`) is supported. `<C-c>` and `<C-z>` are
-- reserved (binding either is an error).
maki.keymap = {}

---Bind a key to a Lua function, like `vim.keymap.set`. A handler that runs
---consumes the key, even if it raises (the error is logged).
---@param mode "n" Mode letter. Currently only `"n"` is accepted.
---@param lhs string Key in Vim notation, e.g. `"<C-t>"`, `"<Space>"`, `"a"`.
---@param rhs fun() Called when the key is pressed; the return value is ignored.
---@param opts? MakiKeymapOpts
function maki.keymap.set(mode, lhs, rhs, opts) end

---Remove your plugin's mapping for `lhs`. Only your own mappings can be
---removed; does nothing if nothing maps `lhs`.
---@param mode string Mode letter (reserved for future modes).
---@param lhs string Key to unmap, in Vim notation.
function maki.keymap.del(mode, lhs) end

---Canonical spelling of `lhs`; returns the string a `key` event carries.
---@param lhs string Key in any accepted notation.
---@return string|nil canonical Canonical notation, or nil plus an error.
---@return string|nil err
function maki.keymap.normalize(lhs) end

