-- Global declaration (standard `---@meta` library convention)
--------------------------------------------------------------------------------

---@type Maki
---Global table exposing the entire plugin API. Provided by the maki host;
---declared here (in a `---@meta` file, this assignment never executes) so
---lua_ls picks up hover/completion in plugin files.
maki = maki
